-- Instants become TIMESTAMPTZ; existing naive values were written by Prisma as UTC,
-- so they are reinterpreted as UTC rather than as the server's local zone.
-- Date-only values become DATE, which removes the midnight/timezone hazard entirely.
ALTER TABLE "organization_settings" ALTER COLUMN "createdAt" TYPE TIMESTAMPTZ(3) USING "createdAt" AT TIME ZONE 'UTC';
ALTER TABLE "organization_settings" ALTER COLUMN "updatedAt" TYPE TIMESTAMPTZ(3) USING "updatedAt" AT TIME ZONE 'UTC';
